"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/voice-agent/variants/01-session";
import Variant1 from "./components/voice-agent/variants/02-dock";
const variants = { session: Variant0, dock: Variant1 };
export interface ArtemisVoiceAgentProps {
  className?: string;
  variant?: "session" | "dock";
}
export function ArtemisVoiceAgent({ className, variant = "session" }: ArtemisVoiceAgentProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}
